t = [0 1 2 3 4];
k = [0.10 0.25 0.35 0.40 0.42];


%%\ 1. Boole's rule
dt = t(2) - t(1);

I_boole = 2*dt/45 * ...
    (7*k(1) + 32*k(2) + 12*k(3) ...
    + 32*k(4) + 7*k(5));

fprintf('Boole integral = %.6f\n', I_boole); %[output:4edc2dbb]

%%\ 2. Heat transferred
Qk = 482.7;              % From Part (b)
H = Qk * I_boole;

fprintf('Heat transferred = %.3f J\n', H); %[output:70d6bd6e]

%%\ 3. Verification using polynomial interpolation
% Fit a fourth-degree polynomial through five points
p = polyfit(t, k, 4);

% Integrate polynomial analytically
P = polyint(p);

% Evaluate definite integral from 0 to 4
I_poly = polyval(P, 4) - polyval(P, 0);

fprintf('Polynomial integral = %.6f\n', I_poly); %[output:164d055f]

%%\ 4. Compare results
fprintf('Difference = %.2e\n', abs(I_boole - I_poly)); %[output:0d402b6a]

% Fourth-degree polynomial interpolation
p = polyfit(t, k, 4);

% Generate smooth interpolating curve
t_fine = linspace(0, 4, 200);
k_fine = polyval(p, t_fine);

% Boole's rule integration
dt = t(2) - t(1);

I = 2*dt/45 * ...
    (7*k(1) + 32*k(2) + 12*k(3) ...
    + 32*k(4) + 7*k(5));

% Create figure
figure; %[output:61e72323]
hold on; %[output:61e72323]

% Shade area under interpolating polynomial
patch([t_fine fliplr(t_fine)], ... %[output:61e72323]
    [zeros(size(t_fine)) fliplr(k_fine)], ... %[output:61e72323]
    [0.65 0.82 1.0], ... %[output:61e72323]
    'FaceAlpha', 0.4, ... %[output:61e72323]
    'EdgeColor', 'none', ... %[output:61e72323]
    'HandleVisibility', 'off'); %[output:61e72323]

% Plot fourth-degree interpolating polynomial
plot(t_fine, k_fine, 'b-', ... %[output:61e72323]
    'LineWidth', 2, ... %[output:61e72323]
    'DisplayName', 'Quartic interpolation'); %[output:61e72323]

% Plot original data points
plot(t, k, 'ro', ... %[output:61e72323]
    'MarkerFaceColor', 'r', ... %[output:61e72323]
    'MarkerSize', 7, ... %[output:61e72323]
    'DisplayName', 'Given data'); %[output:61e72323]

% Vertical lines at data points
for i = 1:length(t)
    plot([t(i) t(i)], [0 k(i)], ... %[output:61e72323]
        'k--', 'LineWidth', 0.8, ... %[output:61e72323]
        'HandleVisibility', 'off'); %[output:61e72323]
end

% Formatting
xlabel('t (s)', 'FontSize', 12); %[output:61e72323]
ylabel('k (W/(m K))', ... %[output:61e72323]
    'FontSize', 12); %[output:61e72323]

title(sprintf('Boole''s Rule (I = %.4f)', I)); %[output:61e72323]

legend('Location', 'southeast'); %[output:61e72323]
grid on; %[output:61e72323]
box on; %[output:61e72323]

xlim([0 4]); %[output:61e72323]
ylim([0 0.5]); %[output:61e72323]
xticks(0:1:4); %[output:61e72323]

set(gca, 'FontSize', 11); %[output:61e72323]
hold off; %[output:61e72323]

% Export for Overleaf after confirming figure displays
exportgraphics(gcf, 'boole_rule.pdf', ... %[output:group:7491da06] %[output:61e72323]
    'ContentType', 'vector'); %[output:group:7491da06] %[output:61e72323]

